# Standard library
import uuid

# Third-party
from sqlalchemy import Boolean, Integer, REAL, Text, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, TimestampMixin


class CompendiumSubPoiAccess(TimestampMixin, Base):
    __tablename__ = "compendium_sub_poi_access"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        comment=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid()."
        ),
    )
    public_transport: Mapped[bool | None] = mapped_column(
        Boolean,
        comment=(
            "Whether the point of interest is reachable by public transport "
            "(bus, train, cable car, etc.)."
        ),
    )
    public_transport_info: Mapped[str | None] = mapped_column(
        Text,
        comment=(
            "Free-text details about public transport access in English (e.g. "
            "nearest stop, line numbers, timetable notes)."
        ),
    )
    public_transport_info_de: Mapped[str | None] = mapped_column(
        Text,
        comment=(
            "German (de) translation of the public transport access details."
        ),
    )
    public_transport_info_pl: Mapped[str | None] = mapped_column(
        Text,
        comment=(
            "Polish (pl) translation of the public transport access details."
        ),
    )
    parking_available: Mapped[bool | None] = mapped_column(
        Boolean,
        comment=(
            "Whether dedicated parking (car park or roadside) is available "
            "near the point of interest."
        ),
    )
    parking_capacity: Mapped[int | None] = mapped_column(
        Integer,
        comment=(
            "Approximate number of parking spaces available at the parking "
            "facility near the point of interest."
        ),
    )
    parking_price: Mapped[float | None] = mapped_column(
        REAL,
        comment=(
            "Indicative parking fee in the local currency (e.g. EUR per day). "
            "NULL means unknown or free."
        ),
    )
    parking_notes: Mapped[str | None] = mapped_column(
        Text,
        comment=(
            "Free-text notes about parking in English (e.g. seasonal "
            "closures, overflow lots, height restrictions)."
        ),
    )
    parking_notes_de: Mapped[str | None] = mapped_column(
        Text,
        comment="German (de) translation of the parking notes.",
    )
    parking_notes_pl: Mapped[str | None] = mapped_column(
        Text,
        comment="Polish (pl) translation of the parking notes.",
    )
    toilet_available: Mapped[bool | None] = mapped_column(
        Boolean,
        comment=(
            "Whether toilet or restroom facilities are available at or near "
            "the point of interest."
        ),
    )
    water_available: Mapped[bool | None] = mapped_column(
        Boolean,
        comment=(
            "Whether potable water (fountain, tap, spring) is available at or "
            "near the point of interest."
        ),
    )
    access_notes: Mapped[str | None] = mapped_column(
        Text,
        comment=(
            "General access notes in English covering any additional "
            "information not captured by the other fields (e.g. road "
            "conditions, gate hours, permit requirements)."
        ),
    )
    access_notes_de: Mapped[str | None] = mapped_column(
        Text,
        comment="German (de) translation of the general access notes.",
    )
    access_notes_pl: Mapped[str | None] = mapped_column(
        Text,
        comment="Polish (pl) translation of the general access notes.",
    )
